pkgload::load_all('.', quiet=TRUE)
metadata <- data.frame(sample_id=c('a0','a1','b0','b1'),subject=c('a','a','b','b'),visit=rep(c('v0','v1'),2))
rec <- function(id) list(unit_id=id,unit_type='subject_delta',representation_id='delta',eligibility='retained',source_sample_ids=paste0(id,0:1),subject_id=id,visit_weights=c(v0=-1,v1=1),study_id='s',analysis_id='x',preparation_context_id='p')
block <- function() {m <- matrix(1:2,1,dimnames=list('f',c('a','b')));list(assay=m,sample_ids=colnames(m),signed_delta_map=m,centered=FALSE,decomposition='target_minus_reference_once',decomposition_count=1L,unit_map=list(rec('a'),rec('b')))}
r <- list(model_plan=list(reference_visit='v0',target_visit='v1'),blocks=list(A=block(),B=block()))
i <- list(sample_metadata=metadata,study_id='s')
a <- list(analysis_id='x',preparation_context_id='p',design=list(representation='delta',subject_id='subject',visit_column='visit'))
for(field in c('unit_type','representation_id','study_id','analysis_id','preparation_context_id')) {bad <- r; bad$blocks$B$unit_map[[1]][[field]] <- 'FOREIGN'; got <- tryCatch(triomics_c06_cli_compose_unit_map(bad,i,a,c('A','B'),r$blocks$A$unit_map),error=identity);cat('PAIRED_SECONDARY_FIELD',field,if(inherits(got,'error')) conditionMessage(got) else paste('ACCEPTED_AND_REWRITTEN',got$unit_map$a[[field]]),'\n')}
md <- data.frame(sample_id=c('a0','a1','absent'),subject=c('a','a','b'),time=c(0,1,0))
m <- matrix(c(1,2),1,dimnames=list('f',c('a0','a1')))
r <- list(blocks=list(A=list(assay=m,sample_ids=colnames(m)),B=list(assay=m,sample_ids=colnames(m))))
i <- list(sample_metadata=md,study_id='s')
a <- list(analysis_id='x',preparation_context_id='p',design=list(representation='subject_centered',subject_id='subject',condition='time',time_column='time',time_unit='day',time_origin='0',visit_column=NULL))
map <- data.frame(unit_id=md$sample_id,representation_id='subject_centered',subject_id=md$subject,condition=as.character(md$time),eligible=c(TRUE,TRUE,FALSE),exclusion_reason=c(NA,NA,'absent_from_all_analysis_blocks'),source_sample_ids=I(as.list(md$sample_id)))
got <- triomics_c06_cli_compose_unit_map(r,i,a,c('A','B'),map)
cat('TRAJECTORY_INPUT_IDS',paste(map$unit_id,collapse=','),'OUTPUT_IDS',paste(got$unit_ids,collapse=','),'OUTPUT_MAP_IDS',paste(names(got$unit_map),collapse=','),'\n')
key <- triomics_clinical_subject_key('s','a')
map <- list(list(unit_id='a0',unit_type='sample',representation_id='levels',source_sample_ids='a0',subject_id='a'))
rv <- list(representation_id='levels',unit_map=map)
cv <- list(links=list(a0=list(subject_key=key)))
got <- tryCatch(triomics_c08_cli_unit_map(rv,data.frame(sample_id='a0',subject_id='a'),NULL,cv),error=identity)
cat('RAW_SUBJECT','a','PUBLIC_SUBJECT_KEY',key,'CLINICAL_UNIT_MAP_RESULT',if(inherits(got,'error')) paste(got$code,conditionMessage(got)) else 'ACCEPTED','\n')
